window.TL9_IMAGES={"background": "data:image/webp;base64,", "arch-symbol": "data:image/webp;base64,", "card-1": "data:image/webp;base64,", "card-2": "data:image/webp;base64,", "card-3": "data:image/webp;base64,", "card-4": "data:image/webp;base64,", "card-5": "data:image/webp;base64,"};
/* Timeline V9: interactive Basque historical chronology, integrated with the ten-game HTML. */
(() => {
  'use strict';
  const KEY='islama-v4-puntuazioak';
  const ROOT_ID='tl9-root';
  const TIME=90;
  const EVENTS=[
    {id:'570',year:570,short:'Mekan jaioa',full:'Mahoma Mekan jaio zen.',image:'card-1'},
    {id:'610',year:610,short:'Hirako agerpena',full:'Gabriel arkanjeluaren agerpena Hirako haitzuloan.',image:'card-2'},
    {id:'622',year:622,short:'Hejira',full:'Mekatik Medinara ihesaldia (Hejira).',image:'card-3'},
    {id:'630',year:630,short:'Mekaren konkista',full:'Meka konkistatu zuen.',image:'card-4'},
    {id:'632',year:632,short:'Mahomaren heriotza',full:'Mahomaren heriotza.',image:'card-5'}
  ];
  const correct=EVENTS.map(e=>e.id);
  const byId=Object.fromEntries(EVENTS.map(e=>[e.id,e]));
  const image=(key)=>window.TL9_IMAGES?.[key]||'';
  const esc=(s)=>String(s).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  let state=null,timer=null,suppressClickUntil=0,drag=null,sound=true,root=null;
  function node(id){return root?.querySelector('#'+id)}
  function randomCards(){const ids=[...correct];do{for(let i=ids.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]]}}while(ids.every((x,i)=>x===correct[i]));return ids}
  function scores(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')}catch{return {}}}
  function leaders(){let a=scores().denbora||{};return Object.values(a).sort((x,y)=>y.score-x.score||x.timestamp-y.timestamp).slice(0,10)}
  function save(score){const all=scores();all.denbora||={};const id=state.nickname.toLocaleLowerCase('eu');const prev=all.denbora[id];if(!prev||prev.score<score){all.denbora[id]={name:state.nickname,score,timestamp:Date.now()};try{localStorage.setItem(KEY,JSON.stringify(all));return true}catch{return false}}return true}
  function setTimer(){if(timer)clearInterval(timer);timer=setInterval(()=>{if(!state||state.done||!state.started)return;state.time=Math.max(0,state.time-1);showHud();if(!state.time)finish(false,'Denbora agortu da!')},1000)}
  function beep(ok){if(!sound)return;try{const A=window.AudioContext||window.webkitAudioContext;const c=new A(),o=c.createOscillator(),v=c.createGain();o.type='sine';o.frequency.value=ok?750:225;v.gain.value=.05;o.connect(v).connect(c.destination);o.start();o.stop(c.currentTime+.13);setTimeout(()=>c.close(),360)}catch{}}
  function shell(){return `<div id="tl9-root" hidden><main id="tl9-stage" aria-label="Mahomaren denbora-lerroa" lang="eu">
      <div class="tl9-scrollwork"></div>
      <header id="tl9-hud">
        <button class="tl9-square tl9-royal" data-action="home" aria-label="Hasierara">⌂</button>
        <div class="tl9-hud-title tl9-royal">2. Mahomaren denbora-lerroa</div>
        <div class="tl9-hearts" id="tl9-lives">❤️❤️❤️</div>
        <div class="tl9-hud-chip" id="tl9-score">Puntuak: 0</div>
        <div class="tl9-hud-chip" id="tl9-time">⏱ 01:30</div>
        <button class="tl9-square tl9-royal" data-action="sound" id="tl9-sound" aria-label="Soinua">🔊</button>
      </header>
      <div id="tl9-instruction">Jarri gertaerak ordena kronologikoan, ezkerretik eskuinera.</div>
      <aside id="tl9-left" class="tl9-parchment">
        <div class="tl9-medallion">2. JOKOA</div><h2>Kronologia-<br>erronka</h2>
        <div class="tl9-art-symbol" style="background-image:url('${image('arch-symbol')}')"></div>
        <p class="tl9-side-instruction">Jarri gertaerak ordena kronologikoan, ezkerretik eskuinera.</p>
        <div class="tl9-completed" id="tl9-count">0/5</div>
        <div class="tl9-hint"><strong>💡 Aholkua</strong>Irakurri gertaerak arretaz eta pentsatu zer gertatu zen lehenago eta zer geroago.<br><small>PDF: 6., 7., 11. eta 31. orrialdeak</small></div>
      </aside>
      <aside id="tl9-right" class="tl9-parchment">
        <div class="tl9-ranking-title">🏆 TOP 10</div><div id="tl9-ranking"></div>
        <div class="tl9-localnote">Ordenagailu honetako errekorrak</div>
      </aside>
      <div id="tl9-core"><div id="tl9-slots" aria-label="Denbora-lerroko bost kokapen"></div><div id="tl9-track"><div class="tl9-beads"><span></span><span></span><span></span><span></span><span></span></div></div><div id="tl9-deck" aria-label="Gertaeren txartelak"></div></div>
      <button id="tl9-removecard" data-action="remove" disabled>↶ Txartela kendu</button>
      <div id="tl9-feedback" role="status" aria-live="polite"></div>
      <button id="tl9-verify" data-action="verify" disabled>✓ Egiaztatu</button>
      <nav id="tl9-lower-nav"><button class="tl9-navbtn" data-action="prev">◀ Aurrekoa</button><div class="tl9-navnums" aria-label="Jokoen zerrenda">${Array.from({length:10},(_,i)=>`<span class="${i===1?'active':''}">${i+1}</span>`).join('')}</div><button class="tl9-navbtn" data-action="next">Hurrengoa ▶</button></nav>
      <div id="tl9-start" aria-labelledby="tl9-start-title"><div class="tl9-modal"><h2 id="tl9-start-title">Mahomaren denbora-lerroa</h2><div class="tl9-illustration"></div><p>Jarri bost gertaerak ordena kronologikoan. Txartelak arrastatu edo hautatu ditzakezu.</p><input id="tl9-nickname" maxlength="18" placeholder="Zure goitizena" aria-label="Zure goitizena"><div class="tl9-invalid" id="tl9-invalid"></div><button data-action="start">▶ Jolastu</button><button class="secondary" data-action="home">Itzuli</button></div></div>
      <div id="tl9-end" hidden><div class="tl9-modal"><h2 id="tl9-end-title">Zorionak!</h2><div style="font-size:42px">🏆</div><p id="tl9-end-desc"></p><h2 id="tl9-end-score">0 puntu</h2><p id="tl9-end-note"></p><button data-action="again">↻ Berriro jokatu</button><button class="secondary" data-action="home">Menura</button></div></div>
  </main><div id="tl9-floating" aria-hidden="true"><img alt=""></div></div>`}
  function launch(){if(!root){document.body.insertAdjacentHTML('beforeend',shell());root=document.getElementById(ROOT_ID);root.style.setProperty('--tl9-scene',`url("${image('background')}")`);root.addEventListener('click',onClick);root.addEventListener('dragstart',onDragStart);root.addEventListener('dragover',onDragOver);root.addEventListener('dragleave',onDragLeave);root.addEventListener('drop',onDrop);root.addEventListener('pointerdown',onPointerDown);window.addEventListener('pointermove',onPointerMove);window.addEventListener('pointerup',onPointerUp);window.addEventListener('pointercancel',cancelPointer);document.addEventListener('keydown',onKeyDown)}root.hidden=false;document.body.style.overflow='hidden';state={nickname:'',started:false,slots:Array(5).fill(null),order:randomCards(),selected:null,errors:0,checks:0,lives:3,time:TIME,done:false,score:0,busy:false};node('tl9-end').hidden=true;node('tl9-start').hidden=false;let previousNick='';try{previousNick=localStorage.getItem('timeline-v9-lastnick')||''}catch{}node('tl9-nickname').value=previousNick;node('tl9-invalid').textContent='';node('tl9-sound').textContent=sound?'🔊':'🔇';setTimeout(()=>node('tl9-nickname')?.focus(),100);render();}
  function close(){if(timer){clearInterval(timer);timer=null}if(root)root.hidden=true;document.body.style.overflow='';state=null;hideGhost()}
  function begin(name){name=(name||'').trim().normalize('NFC');if(!/^[\p{L}\p{N}_ -]{2,18}$/u.test(name)){node('tl9-invalid').textContent='2–18 karaktereko goitizena idatzi, mesedez.';return false}try{localStorage.setItem('timeline-v9-lastnick',name)}catch{}state={nickname:name,started:true,slots:Array(5).fill(null),order:randomCards(),selected:null,errors:0,checks:0,lives:3,time:TIME,done:false,score:0,busy:false};node('tl9-start').hidden=true;node('tl9-end').hidden=true;node('tl9-feedback').className='';node('tl9-feedback').textContent='';render();setTimer();return true}
  function showHud(){if(!state)return;node('tl9-lives').textContent='❤️'.repeat(state.lives)+'🖤'.repeat(3-state.lives);node('tl9-score').textContent='Puntuak: '+state.score.toLocaleString('eu-ES');node('tl9-time').textContent='⏱ '+String(Math.floor(state.time/60)).padStart(2,'0')+':'+String(state.time%60).padStart(2,'0')}
  function renderRanking(){const leadersNow=leaders(),list=node('tl9-ranking');if(!list)return;list.innerHTML=leadersNow.length?leadersNow.map((r,i)=>`<div class="tl9-rank-row"><span class="tl9-rank-num">${i<3?['🥇','🥈','🥉'][i]:i+1+'.'}</span><span class="tl9-rank-name">${esc(r.name)}</span><span class="tl9-rank-score">${Number(r.score).toLocaleString('eu-ES')}</span></div>`).join(''):`<div class="tl9-empty">Oraindik ez dago puntuaziorik.<br><br>Izan zaitez lehena!</div>`}
  function card(e){return `<img src="${image(e.image)}" alt=""><span class="tl9-move" aria-hidden="true">✥</span><span class="tl9-card-caption">${esc(e.short)}</span>`}
  function draw(){if(!state)return;const slots=node('tl9-slots'),deck=node('tl9-deck');slots.innerHTML=state.slots.map((id,idx)=>`<button class="tl9-slot" data-slot="${idx}" aria-label="${idx+1}. kokapena${id?': '+byId[id].full:': hutsik'}">${id?`<span class="tl9-slot-card"><img src="${image(byId[id].image)}" alt="">${esc(byId[id].short)}</span>`:''}</button>`).join('');deck.innerHTML=state.order.map(id=>{const e=byId[id],placed=state.slots.includes(id);return placed?`<div class="tl9-card tl9-placeholder" data-placeholder="${id}" title="Dagoeneko kokatuta">✓<small>Kokatuta</small></div>`:`<button class="tl9-card ${state.selected===id?'tl9-selected':''}" data-card="${id}" draggable="true" aria-label="${esc(e.full)}. Hautatu eta gero kokapen bat sakatu">${card(e)}</button>`}).join('');node('tl9-count').textContent=state.slots.filter(Boolean).length+'/5';node('tl9-removecard').disabled=!state.selected||!state.slots.includes(state.selected)||state.busy||state.done;node('tl9-verify').disabled=!state.started||state.busy||state.done}
  function render(){showHud();renderRanking();draw()}
  function select(id){if(!state||state.done||state.busy)return;state.selected=state.selected===id?null:id;draw()}
  function place(id,idx){if(!state||state.done||state.busy||!byId[id]||idx<0||idx>4)return;const old=state.slots.indexOf(id),occupant=state.slots[idx];if(old===idx){state.selected=null;draw();return}if(old!==-1)state.slots[old]=occupant||null;state.slots[idx]=id;state.selected=null;clearFeedback();draw();beep(true)}
  function remove(id){if(!state||!id)return;const idx=state.slots.indexOf(id);if(idx!==-1){state.slots[idx]=null;state.selected=null;clearFeedback();draw()}}
  function clearFeedback(){node('tl9-feedback').className='';node('tl9-feedback').textContent='';root.querySelectorAll('.tl9-slot').forEach(n=>n.classList.remove('tl9-error','tl9-success'))}
  function feedback(text,good){const el=node('tl9-feedback');el.textContent=text;el.className='on '+(good?'good':'bad')}
  function verify(){if(!state||!state.started||state.busy||state.done)return;if(state.slots.some(x=>!x)){feedback('Osatu bost gertaerak egiaztatu aurretik. Ez duzu bizitzarik galdu.','bad');return;}const checkRound=state;state.checks++;const wrong=[];for(let i=0;i<5;i++)if(state.slots[i]!==correct[i])wrong.push(i);state.busy=true;if(wrong.length){state.errors++;state.lives--;beep(false);feedback('Ez da zuzena. Berrikusi ordena.','bad');wrong.forEach(i=>root.querySelector(`[data-slot="${i}"]`)?.classList.add('tl9-error'));showHud();if(!state.lives){setTimeout(()=>{if(state===checkRound)finish(false,'Bizitzak agortu dira!')},850);return}setTimeout(()=>{if(state===checkRound&&!state.done){state.busy=false;clearFeedback();draw()}},1100)}else{beep(true);state.score=Math.max(0,Math.min(1000,800-Math.max(0,state.checks-1)*120+Math.round(200*state.time/TIME)));feedback('Bikain! Kronologia osatu duzu!','good');root.querySelectorAll('.tl9-slot').forEach(el=>el.classList.add('tl9-success'));showHud();setTimeout(()=>{if(state===checkRound)finish(true,'Kronologia osatu duzu!')},1100)}}
  function finish(won,detail){if(!state||state.done)return;state.done=true;state.busy=false;if(timer){clearInterval(timer);timer=null}if(!won)state.score=0;const stored=won?save(state.score):false;showHud();renderRanking();node('tl9-end-title').textContent=won?'Zorionak!':'Partida amaitu da';node('tl9-end-desc').textContent=detail;node('tl9-end-score').textContent=state.score.toLocaleString('eu-ES')+' puntu';node('tl9-end-note').textContent=won?(stored?'Zure puntuazioa ordenagailu honetan gorde da.':'Ez da errekorra gorde: biltegiratzea mugatuta dago.'):'Beste partida bat jokatu eta saiatu berriro!';node('tl9-end').hidden=false}
  function navigate(which){close();const target=which==='prev'?'arabia':'bost';const tile=document.querySelector(`.game-tile[data-game="${target}"]`);tile?.click()}
  function onClick(e){if(!state||root.hidden||Date.now()<suppressClickUntil)return;const action=e.target.closest('[data-action]')?.dataset.action;if(action){e.preventDefault();switch(action){case'home':close();break;case'start':begin(node('tl9-nickname').value);break;case'again':begin(state.nickname);break;case'sound':sound=!sound;node('tl9-sound').textContent=sound?'🔊':'🔇';break;case'remove':remove(state.selected);break;case'verify':verify();break;case'prev':case'next':navigate(action);break}return}if(!state.started||state.done||state.busy)return;const c=e.target.closest('[data-card]'),slot=e.target.closest('[data-slot]');if(c){select(c.dataset.card);return}if(slot){const idx=+slot.dataset.slot;if(state.selected){place(state.selected,idx)}else if(state.slots[idx])select(state.slots[idx]);return}}
  function onKeyDown(e){if(root?.hidden)return;if(e.key==='Escape'){if(drag)cancelPointer();else if(state?.selected){state.selected=null;draw()}else close()}if(e.key==='Enter'&&e.target.id==='tl9-nickname')begin(node('tl9-nickname').value);if((e.key==='Delete'||e.key==='Backspace')&&state?.selected&&state.slots.includes(state.selected)){e.preventDefault();remove(state.selected)}}
  function onDragStart(e){const cardEl=e.target.closest('[data-card]');if(!cardEl||!state?.started||state.busy){e.preventDefault();return}e.dataTransfer?.setData('text/plain',cardEl.dataset.card);e.dataTransfer.effectAllowed='move'}
  function onDragOver(e){const slot=e.target.closest('[data-slot]');if(slot||e.target.closest('#tl9-deck')){e.preventDefault();if(slot)slot.classList.add('drag-over')}}
  function onDragLeave(e){e.target.closest('[data-slot]')?.classList.remove('drag-over')}
  function onDrop(e){const slot=e.target.closest('[data-slot]');e.preventDefault();root.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));const id=e.dataTransfer?.getData('text/plain')||state?.selected;if(slot&&id)place(id,+slot.dataset.slot);else if(e.target.closest('#tl9-deck')&&id)remove(id)}
  function onPointerDown(e){const cardEl=e.target.closest('[data-card], [data-slot]');if(!cardEl||e.pointerType==='mouse'||!state?.started||state.busy)return;const id=cardEl.dataset.card||state.slots[+cardEl.dataset.slot];if(!id)return;drag={id,x:e.clientX,y:e.clientY,moved:false,pointerId:e.pointerId};}
  function onPointerMove(e){if(!drag||e.pointerId!==drag.pointerId)return;if(!drag.moved&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>11){drag.moved=true;const f=node('tl9-floating');f.querySelector('img').src=image(byId[drag.id].image);f.style.display='block';suppressClickUntil=Date.now()+300}if(drag.moved){const f=node('tl9-floating');f.style.left=e.clientX+'px';f.style.top=e.clientY+'px';root.querySelectorAll('.drag-over').forEach(el=>el.classList.remove('drag-over'));const beneath=document.elementFromPoint(e.clientX,e.clientY);beneath?.closest('[data-slot]')?.classList.add('drag-over')}}
  function onPointerUp(e){if(!drag||e.pointerId!==drag.pointerId)return;const d=drag;drag=null;hideGhost();if(!d.moved)return;suppressClickUntil=Date.now()+320;const beneath=document.elementFromPoint(e.clientX,e.clientY),slot=beneath?.closest('[data-slot]');if(slot)place(d.id,+slot.dataset.slot);else if(beneath?.closest('#tl9-deck'))remove(d.id)}
  function hideGhost(){const f=node('tl9-floating');if(f)f.style.display='none';root?.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'))}
  function cancelPointer(){drag=null;hideGhost()}
  window.TIMELINE_V9={launch,close,testStart:(name='Proba21')=>{launch();return begin(name)},getState:()=>state&&({...state,slots:[...state.slots]}),placeForTest:place,verifyForTest:verify,getScoresForTest:leaders};
})();

